import React from "react";
import { FaSearch, FaFilter } from "react-icons/fa";
import TechnicianItem from "./TechnicianItemComponent";
import FilterSheet from "./FilterSheetComponent";
import AuthCheck from "./AuthCheckComponent";

const API_URL = "https://iranaserviceapp.ir/test/api";

class TechniciansPage extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      // کل پاسخ JSON از API
      userData: null,

      // لیست قابل نمایش
      technicians: [],

      // فقط برای سرچ اسم
      searchTerm: "",

      // فیلتر فعلاً استفاده نمی‌شود
      isFilterOpen: false,
      filterProvince: "",
      filterCity: "",
      filterSpecialty: "",

      loading: true,
      authenticated: false,
    };

    this.getTechnicians = this.getTechnicians.bind(this);
    this.handleSearchChange = this.handleSearchChange.bind(this);
    this.handleSearch = this.handleSearch.bind(this);

    this.openFilter = this.openFilter.bind(this);
    this.closeFilter = this.closeFilter.bind(this);
    this.applyFilter = this.applyFilter.bind(this);

    this.handleDelete = this.handleDelete.bind(this);
    this.handleToggleStatus = this.handleToggleStatus.bind(this);
    this.handleDetails = this.handleDetails.bind(this);
  }

  componentDidMount() {
    if (!AuthCheck()) {
      return;
    }

    this.setState(
      {
        authenticated: true,
      },
      () => {
        this.getTechnicians();
      }
    );
  }

  // ==========================================
  // GET USERS
  // ==========================================

  getTechnicians() {
    const token = localStorage.getItem("token");

    fetch(`${API_URL}/users`, {
      method: "GET",
      headers: {
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },
    })
      .then((response) => response.json())
      .then((data) => {
        console.log("USERS API:", data);

        // کل JSON داخل state ذخیره می‌شود
        this.setState(
          {
            userData: data,
            loading: false,
          },
          () => {
            // بعد از دریافت اطلاعات،
            // لیست اولیه را بساز
            this.handleSearch();
          }
        );
      })
      .catch((error) => {
        console.error("GET USERS ERROR:", error);

        this.setState({
          userData: null,
          technicians: [],
          loading: false,
        });
      });
  }

  // ==========================================
  // گرفتن لیست کاربران از JSON
  // ==========================================

  getUsers() {
    const { userData } = this.state;

    if (!userData) {
      return [];
    }

    if (Array.isArray(userData.users)) {
      return userData.users;
    }

    return [];
  }

  // ==========================================
  // تغییر متن سرچ
  // ==========================================

  handleSearchChange(e) {
    const value = e.target.value;

    this.setState(
      {
        searchTerm: value,
      },
      () => {
        this.handleSearch();
      }
    );
  }

  // ==========================================
  // سرچ اسم
  // ==========================================

  handleSearch() {
    const users = this.getUsers();
    const search = this.state.searchTerm.trim().toLowerCase();

    let result = users;

    if (search !== "") {
      result = users.filter((user) => {
        const fullName =
          `${user.name || ""} ${user.family || ""}`
            .trim()
            .toLowerCase();

        return fullName.includes(search);
      });
    }

    const technicians = result.map((user) => ({
      ...user,

      id: user.id,

      name:
        `${user.name || ""} ${user.family || ""}`.trim() ||
        "بدون نام",

      status:
        Number(user.active) === 1
          ? "free"
          : "blocked",

      avatar: user.image
        ? `https://iranaserviceapp.ir/test/${user.image}`
        : `https://ui-avatars.com/api/?name=${encodeURIComponent(
            `${user.name || ""} ${user.family || ""}`
          )}&background=e9ecef&color=495057`,
    }));

    this.setState({
      technicians: technicians,
    });
  }

  // ==========================================
  // فیلتر
  // فعلاً هیچ کاری نمی‌کند
  // ==========================================

  openFilter() {
    this.setState({
      isFilterOpen: true,
    });
  }

  closeFilter() {
    this.setState({
      isFilterOpen: false,
    });
  }

  applyFilter() {
    // فعلاً فیلتر استان، شهر و تخصص
    // هیچ کاری انجام نمی‌دهد

    this.closeFilter();
  }

  // ==========================================
  // DELETE
  // POST /delete
  // ==========================================

  handleDelete(id) {
    const token = localStorage.getItem("token");

    fetch(`${API_URL}/delete`, {
      method: "POST",

      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },

      body: JSON.stringify({
        id: id,
      }),
    })
      .then((response) => response.json())
      .then((data) => {
        console.log("DELETE USER:", data);

        if (String(data.status) === "1") {
          this.setState(
            (prevState) => {
              if (!prevState.userData) {
                return null;
              }

              const users = Array.isArray(
                prevState.userData.users
              )
                ? prevState.userData.users
                : [];

              return {
                userData: {
                  ...prevState.userData,

                  users: users.filter(
                    (user) => user.id !== id
                  ),
                },
              };
            },
            () => {
              // لیست دوباره ساخته شود
              this.handleSearch();
            }
          );
        }
      })
      .catch((error) => {
        console.error("DELETE USER ERROR:", error);
      });
  }

  // ==========================================
  // ACTIVE
  // POST /active
  // فقط ID
  // ==========================================

  handleToggleStatus(id, currentStatus) {
    const token = localStorage.getItem("token");

    fetch(`${API_URL}/active`, {
      method: "POST",

      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },

      body: JSON.stringify({
        id: id,
      }),
    })
      .then((response) => response.json())
      .then((data) => {
        console.log("ACTIVE USER:", data);

        if (String(data.status) === "1") {
          this.setState(
            (prevState) => {
              if (!prevState.userData) {
                return null;
              }

              const users = Array.isArray(
                prevState.userData.users
              )
                ? prevState.userData.users
                : [];

              return {
                userData: {
                  ...prevState.userData,

                  users: users.map((user) => {
                    if (user.id !== id) {
                      return user;
                    }

                    return {
                      ...user,

                      active:
                        Number(user.active) === 1
                          ? 0
                          : 1,
                    };
                  }),
                },
              };
            },
            () => {
              // لیست دوباره ساخته شود
              this.handleSearch();
            }
          );
        }
      })
      .catch((error) => {
        console.error("ACTIVE USER ERROR:", error);
      });
  }

  // ==========================================
  // جزئیات
  // ==========================================

  handleDetails(id) {
    console.log("جزئیات تعمیرکار:", id);
  }

  // ==========================================
  // RENDER
  // ==========================================

  render() {
    if (!this.state.authenticated) {
      return null;
    }

    const {
      technicians,
      searchTerm,
      isFilterOpen,
      filterProvince,
      filterCity,
      filterSpecialty,
      loading,
    } = this.state;

    if (loading) {
      return (
        <div className="text-center text-muted py-5">
          در حال دریافت تعمیرکاران...
        </div>
      );
    }

    return (
      <div dir="rtl">
        <div className="container px-3 pt-3">

          {/* =========================
              سرچ اسم
          ========================== */}

          <div className="d-flex align-items-center gap-2 border rounded-pill px-3 py-2 mb-3 bg-white">

            <input
              type="text"
              placeholder="جستجو..."
              value={searchTerm}
              onChange={this.handleSearchChange}
              className="form-control border-0 shadow-none text-end p-0"
            />

            <FaSearch
              className="text-secondary"
              size={16}
            />

          </div>

          {/* =========================
              فیلتر
              فعلاً غیرفعال از نظر منطق
          ========================== */}

          <div className="d-flex justify-content-end mb-3">

            <button
              type="button"
              onClick={this.openFilter}
              className="btn btn-light border rounded-pill d-flex align-items-center gap-2 px-3 py-2"
              style={{
                transition:
                  "background-color 0.15s ease",
              }}
            >
              <span>فیلتر</span>

              <FaFilter
                className="text-secondary"
                size={14}
              />
            </button>

          </div>

          {/* =========================
              عنوان
          ========================== */}

          <div className="bg-light text-center rounded-3 py-3 mb-1">

            <span className="text-primary fw-semibold">
              تعمیرکاران
            </span>

          </div>

          {/* =========================
              لیست
          ========================== */}

          <div>

            {technicians.map((technician) => (
              <TechnicianItem
                key={technician.id}
                technician={technician}
                onDelete={this.handleDelete}
                onToggleStatus={
                  this.handleToggleStatus
                }
                onDetails={this.handleDetails}
              />
            ))}

            {technicians.length === 0 && (
              <div className="text-center text-muted py-5">
                موردی یافت نشد
              </div>
            )}

          </div>

        </div>

        {/* =========================
            Filter Sheet
        ========================== */}

        <FilterSheet
          isOpen={isFilterOpen}
          onClose={this.closeFilter}
          onApply={this.applyFilter}

          province={filterProvince}
          city={filterCity}
          specialty={filterSpecialty}

          onProvinceChange={(e) =>
            this.setState({
              filterProvince: e.target.value,
            })
          }

          onCityChange={(e) =>
            this.setState({
              filterCity: e.target.value,
            })
          }

          onSpecialtyChange={(e) =>
            this.setState({
              filterSpecialty: e.target.value,
            })
          }
        />

      </div>
    );
  }
}

